 if effect=='flip':lab=f'<span class="flip-label" aria-hidden="true"><span>{E(text)}</span><span>{E(text)}</span></span>'
 ico=arrow()
 if effect=='icon-exchange':ico='<span class="icon-slot">'+arrow()+icon('arrow-up-right')+'</span>'
 return f'<a class="button {style} {effect}" href="{E(href)}" aria-label="{E(text)}" {extra}>{lab}{ico}</a>'
