def workflow_motion(route):
 if route=='/how-it-works':return 'data-reviewed-loop'
 slug=route.strip('/').split('/')[-1]
 return 'data-workflow-hero="'+slug+'"' if route.startswith('/workflows/') and slug!='workflows' else ''
def scene(route,extra=''):
 p=PLAN[route];override=SITE/'source'/p['asset']
 if override.exists():shutil.copyfile(override,A/p['asset'])
 s=(override if override.exists() else KIT/p['asset']).read_text();s=s.replace('<svg ', '<svg class="scene-svg" ',1)
 if route=='/how-it-works':
  delays=[0,700,1400,2800,3500]
  count=[0]
  def loop_step(match):
   i=count[0];count[0]+=1
   return '<g class="loop-step" style="--loop-delay:'+str(delays[i])+'ms">'+match.group(0).replace('class="settle d'+str(i)+'"','')+'</g>'
  s=re.sub(r'<circle[^>]+/>\s*<text[^>]*>.*?</text>\s*<text[^>]*>.*?</text>',loop_step,s)
  s=s.replace('<path d="M85 221H798" class="line trace"/>','<path d="M85 221H798" class="line loop-baseline"/>'+''.join('<path d="M'+str(x)+' 221H'+str(x+178)+'" class="line loop-trace" style="--loop-delay:'+str(d)+'ms"/>' for x,d in [(85,350),(263,1050),(441,2450),(619,3150)]))
  s=s.replace('<g class="settle"><rect x="292"','<g class="loop-gate" style="--loop-delay:2100ms"><rect x="292"')
 return f'<div class="visual-frame scene-motion {p["surface"]} {extra}" data-motion {workflow_motion(route)}><div class="frame-top"><span>EXEMPTLINK / {E(p["page"]).upper()}</span><span>CONCEPT PREVIEW</span></div>{s}<div class="scene-mobile"><div class="eyebrow">{"Brand illustration" if route=="/about" else "Illustrative mobile scene"}</div>{mobile_art(route)}<h3>{E(p["hero"])}</h3><p>{E(p["mobile"])}</p>{"" if route=="/about" else badge("Human review required","warning")}</div><div class="frame-bottom"><span>{"BRAND ILLUSTRATION" if route=="/about" else "DEMO — SYNTHETIC DATA"}</span><span>{"A reviewable connection" if route=="/about" else "Finite sequence · reviewed states"}</span></div></div>'
