 if kind in ['pilot','demo']:fields+=field('Your role','role',options=[(x,x) for x in ['Indirect-tax director','Controller','Tax accountant / reviewer','Sales-tax adviser','ERP implementer','Other role']])
 if kind=='pilot':fields+=field('US multistate B2B seller with exempt customers?','buyer_fit',options=[('yes','Yes'),('no','No'),('adviser','I advise one'),('unsure','Not sure')])+field('Proposed pilot state','state',options=[(x,x) for x in STATES])+field('Workflow to evaluate','offer_id',options=[(str(o['id']),o['name']) for o in OFFERS]+[('choose','Help me choose')])+field('Current certificate / tax tool','current_tool',required=False,placeholder='Product or current process')+field('Exempt-sales volume','volume_band',required=False,options=[(x,x) for x in ['Under 1,000/month','1,000–10,000/month','Over 10,000/month','Not yet scoped']])+field('Main review question','challenge','textarea',False,full=True,help='Business context only. No raw tax, financial or customer records.')
 if kind=='demo':fields+=field('Workflow interest','offer_id',options=[(str(o['id']),o['name']) for o in OFFERS]+[('overview','Overview')])+field('Question or preferred meeting window','question','textarea',False,full=True)
 if kind=='early':fields+=field('Company','company',required=False)+field('Role','role',required=False)+field('Workflow interest','offer_id',required=False,options=[(str(o['id']),o['name']) for o in OFFERS])
 if kind=='contact':fields+=field('Topic','topic',options=[(x,x) for x in ['Pilot research','Workflow question','Adviser / implementer referral','Website / preview question']])+field('Message','message','textarea',True,full=True,help='Do not include tax records or customer information.')
 if kind=='privacy':fields+=field('Request type','topic',options=[(x,x) for x in ['Deletion request','Access question','Unsubscribe / purpose question','Other privacy question']])+field('Request context','message','textarea',False,full=True,help='No government IDs, customer records or financial information.')
 consent='I agree to be contacted about this proposed '+('pilot' if kind=='pilot' else 'walkthrough' if kind=='demo' else 'request')+'. I understand this website demonstrates a research-stage concept.'
 if kind=='early':consent='I explicitly opt in to ExemptLink research and early-access updates.'
 form='<div class="intake-layout"><div class="intake-context"><span class="eyebrow">What happens here</span><h2>A reviewable draft.<br><em>Clear delivery status.</em></h2><ol><li>Enter business context only.</li><li>Review the request summary locally.</li><li>Download the draft if useful.</li></ol><div class="notice"><b>Preview intake / nothing is sent.</b><p>Delivery and subscription services are not connected. This form does not transmit your details, create a lead or book a meeting.</p></div><p class="small">An operating contact mechanism and approved policy details are required before public lead collection.</p>'+btn('Inspect the synthetic demo','/demo/','text','icon-exchange')+'</div><form class="intake-form" data-form="'+kind+'" novalidate><div class="form-grid">'+fields+'</div><label class="consent"><input type="checkbox" name="consent" required><span>'+consent+' <a href="/privacy/">Privacy notice</a>.</span></label>'+( '<label class="consent"><input type="checkbox" name="updates"><span>Send me occasional research and early-access updates. Separate optional purpose.</span></label>' if kind=='pilot' else '')+'<p class="form-error" role="alert"></p><button class="button primary shutter" type="submit">'+submit+arrow()+'</button><p class="fine-print">Preview only — nothing submitted. No purchase, delivery or consent-record event is emitted.</p><div class="form-result" hidden role="status"><span class="eyebrow">Local draft / not delivered</span><h3>Review your request.</h3><p>Your entries are shown below. Nothing has been submitted or stored as a lead.</p><dl class="draft-summary"></dl><button type="button" class="button outline draft-download">Download local draft '+icon('download')+'</button><button type="button" class="button text draft-edit">Edit entries '+arrow()+'</button></div></form></div>'
 return hero(route,kicker,title,desc,[( 'Enter business context','#intake','primary'),('Inspect synthetic demo','/demo/','outline')])+section(form,'white','intake')+section(heading('The boundaries','Scope before access.')+content_cards([('Permission','A conversation is not data access','Sample review requires a later agreement about records, transfer, retention and reviewer responsibility.','/pilot/','Read pilot protocol'),('Outreach','Contact consent is purpose-specific','Permission to discuss a pilot is not permission to contact missing-certificate customers. Scripts and recipients are separate.','/controls/','Read controls'),('Commercial','A draft is not a commitment','Only a scoped, signed and funded pilot counts as the demand signal. Clicks and local drafts do not.','/resources/evaluation-method/','Read evaluation method')]),'paper')
